def compute_max_radii(centers):
    """
    Compute maximum radii using iterative constraint propagation.
    """
    n = centers.shape[0]

    # Start with border-constrained radii
    radii = np.zeros(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y)

    # Build distance matrix
    dists = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1, n):
            dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            dists[i, j] = dist
            dists[j, i] = dist

    # Multiple passes: first aggressive, then proportional
    for _ in range(50):
        for i in range(n):
            for j in range(i + 1, n):
                if radii[i] + radii[j] > dists[i, j]:
                    if radii[i] > radii[j]:
                        radii[i] = dists[i, j] - radii[j]
                    else:
                        radii[j] = dists[i, j] - radii[i]

    for _ in range(50):
        for i in range(n):
            for j in range(i + 1, n):
                if radii[i] + radii[j] > dists[i, j]:
                    total = radii[i] + radii[j]
                    if total > 0:
                        scale = dists[i, j] / total
                        radii[i] *= scale
                        radii[j] *= scale

    return radii
